S=[]
def pos(y,t,x=76,w=928,cls='critical text'):
 return f'<div class="pos {cls}" style="left:{x}px;top:{y}px;width:{w}px">{t}</div>'
def h(t,size=100):return f'<h1 style="font-size:{size}px">{t}</h1>'
